"""One-off generator for shape, actions and watchout rules (2026-10-12). Edit the YAML files directly after this."""
import os, yaml
ROOT = os.path.join(os.path.dirname(__file__), "..", "rules")
DATE = r'(?:\b(?:by|on|until|before|through|after)\s+(?:(?:mon|tue|wed|thu|fri|sat|sun)[a-z]*\b|(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+\d{1,2}\b|\d{1,2}/\d{1,2}\b)|\bnext\s+(?:week|month|call)\b)'
THRESH = r'(?:[$€£]\s?\d|\d\s?%|\b(?:above|below|over|under)\s+[$€£]?\d)'
R = [
# ---------- shape ----------
dict(category="shape", slug="title-case-headings", name="Title Case headings", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'(?m)^#{1,6}[ \t]+(?-i:(?:[A-Z][a-z]+[ \t]+){2,}[A-Z][a-z]+)[ \t]*$'],
  message="Title Case heading: '{match}'",
  why="Title Case on every heading is a template habit. Sentence-case headings that state a point read like a person wrote them.",
  fix="Use sentence case, and make the heading say the point ('Sunday costs the most') or drop it.",
  examples={"flag": ["## Weekly Performance Overview Summary"], "pass": ["## Sunday costs the most per conversion"]}),
dict(category="shape", slug="bold-label-bullets", name="Bold-label bullets in bulk", severity="warning", engine="count", applies_to="text",
  count={"pattern": r'(?m)^[ \t]*(?:[-*•]|\d+\.)[ \t]+\*\*[^*\n]{1,40}:?\*\*:?', "max": 3, "per": "report"},
  message="More than 3 bold-label bullets: '{match}'",
  why="'**Label:** sentence' on every bullet is the most recognizable AI layout. It slows reading because the eye stops at every label.",
  fix="Write the bullets as plain sentences, or turn the set into two or three short lines.",
  examples={"flag": ["- **Spend:** up 12%.\n- **CPA:** up 39%.\n- **Conversions:** down 19%.\n- **CTR:** flat.\n- **Next steps:** swap creative."],
            "pass": ["- Spend up 12%.\n- CPA up 39%.\n- Conversions down 19%."]}),
dict(category="shape", slug="bullet-wall", name="Wall of bullets", severity="warning", engine="count", applies_to="text",
  count={"pattern": r'(?m)^[ \t]*(?:[-*•]|\d+\.)[ \t]+\S', "max": 8, "per": "report"},
  message="More than 8 bullets: '{match}'",
  why="A long bullet list has no hierarchy. The reader can't tell which line matters.",
  fix="Keep the 3 to 5 bullets that change the decision. Cut or merge the rest.",
  examples={"flag": ["\n".join(f"- Item {i} changed." for i in range(1, 11))], "pass": ["- Spend up 12%.\n- CPA up 39%.\n- Swap creative on PR-03 by Wed."]}),
# ---------- actions ----------
dict(category="actions", slug="monitor-as-action", name="Monitor as the action", severity="error", engine="regex", applies_to="text",
  patterns=[r'\b(?:continue|keep|will)\s+(?:to\s+)?monitor(?:ing)?\b', r'\bkeep\s+an\s+eye\s+on\b', r'\bmonitor(?:ing)?\s+(?:closely|performance|results|trends|the\s+situation)\b', r'\bwatch\s+(?:this|it|closely)\b'],
  unless=f'^(?=[\\s\\S]*?{DATE})(?=[\\s\\S]*?{THRESH})',
  message="'{match}' isn't an action",
  why="'Monitor' tells the reader nothing will happen. A check needs a date and a number that decides the next step.",
  fix="Name the check: 'If CPA is above $50 on Fri, cut PR-03 budget 40%.' If nothing is due, write 'Nothing to change. Next check: Fri.'",
  examples={"flag": ["We will continue to monitor performance closely.", "Keep an eye on Sunday CPA."],
            "pass": ["Monitor Sunday CPA: if it's above $120 by Oct 20, cut Sunday bids 20%.", "Nothing to change. Next check: Friday."]}),
dict(category="actions", slug="vague-optimize", name="Vague 'optimize'", severity="warning", engine="regex", applies_to="text",
  patterns=[r'\b(?:continue|keep)\s+(?:to\s+)?optimi[sz](?:e|ing)\b', r'\bfurther\s+optimi[sz](?:e|ation|ations)\b', r'\boptimi[sz]e\s+(?:the\s+)?(?:campaigns?|account|performance|keywords,?\s+bids)\b', r'\boptimi[sz]ation\s+opportunities\b'],
  message="Vague action: '{match}'",
  why="'Optimize' with no object, lever or number is a placeholder for an action. Clients read it as the agency having no plan.",
  fix="Say the lever and the size: 'Add 41 negative keywords', 'Raise the tROAS target from 400% to 450%'.",
  examples={"flag": ["We recommend continuing to optimize keywords, bids and ad copy.", "There are several optimization opportunities."],
            "pass": ["Add the 41 negative keywords in the appendix today."]}),
dict(category="actions", slug="too-many-actions", name="Too many actions", severity="advisory", engine="count", applies_to="text",
  count={"pattern": r'(?m)^[ \t]*(?:[-*•]|\d+\.)[ \t]+(?:increase|decrease|raise|lower|add|pause|stop|launch|test|shift|move|cut|expand|scale|review|update|create|consider|optimi[sz]e|refresh|swap|exclude|split)\b', "max": 3, "per": "report"},
  message="More than 3 recommended actions: '{match}'",
  why="Changing many things at once means nobody can tell what worked. Practitioners have watched AI 'fix everything' and tank accounts.",
  fix="Keep the one to three changes that matter most. Change one variable per campaign at a time.",
  examples={"flag": ["- Raise budgets.\n- Pause Display.\n- Test new creative.\n- Add negatives.\n- Shift spend to PMax."],
            "pass": ["- Swap creative on PR-03 by Wed.\n- If CPA isn't under $50 by Fri, move 40% of its budget to retargeting."]}),
dict(category="actions", slug="test-without-stop", name="Test with no stop condition", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'\b(?:test|trial|experiment\s+with)\s+(?:a\s+|new\s+|different\s+)?(?:creative|audiences?|bids?|bidding|landing\s+pages?|copy|headlines?|budgets?)\b'],
  unless=r'(?:\bif\b|\buntil\b|\bstop\b|\bend\b|\broll\s*back\b|\brevert\b|\bfor\s+\d+\s+(?:days|weeks)\b|\bafter\s+\d+\s+(?:conversions|clicks|days)\b)',
  message="Test with no stop condition: '{match}'",
  why="A test with no end date or success bar runs forever and proves nothing.",
  fix="Add the stop condition: how long, what result counts, and what happens if it fails.",
  examples={"flag": ["Next month we will test new creative on prospecting."],
            "pass": ["Test new creative on PR-03 for 14 days; if CPA isn't under $50, revert."]}),
# ---------- watchouts (run on the ORIGINAL, advisory) ----------
dict(category="watchout", slug="micros-cost", name="Cost that looks like micros", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'\b(?:cost|spend|spent|cpc|cpa)\b[^.\n]{0,25}?\$?\s?\d{1,3}(?:,\d{3}){3,}\b', r'\bcost_micros\b'],
  message="This cost may be in micros: '{match}'",
  why="The Google Ads API reports cost in micros (1,000,000 = $1). An unconverted value looks a million times too big.",
  fix="Check the source. If it's micros, divide by 1,000,000 before the number goes anywhere.",
  examples={"flag": ["Total cost was 48,213,000,000 for the week."], "pass": ["Total cost was $48,213 for the week."]}),
dict(category="watchout", slug="lever-vs-bid-strategy", name="Lever that doesn't fit the bid strategy", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'\b(?:t?CPA|target\s+CPA)\b[^.\n]{0,60}\b(?:t?ROAS|target\s+ROAS)\s+campaigns?\b', r'\b(?:t?ROAS|target\s+ROAS)\b[^.\n]{0,60}\b(?:t?CPA|target\s+CPA)\s+campaigns?\b', r'\b(?:keyword|manual|max\s+CPC)\s+bids?\b[^.\n]{0,60}\b(?:smart\s+bidding|maximi[sz]e\s+conversions|t?ROAS|t?CPA)\b'],
  message="This lever may not exist under that bid strategy: '{match}'",
  why="AI often recommends tCPA changes on tROAS campaigns, or keyword bids under Smart Bidding. The setting doesn't exist there.",
  fix="Check the campaign's bid strategy and only keep levers it actually uses.",
  examples={"flag": ["Lower the tCPA target on the tROAS campaigns.", "Raise keyword bids on the Maximize Conversions campaigns."],
            "pass": ["Raise the tROAS target from 400% to 450% on Search - Brand."]}),
dict(category="watchout", slug="short-trend", name="Trend called on too few days", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'\b(?:over|in|across|during)\s+the\s+(?:last|past)\s+(?:[1-6]|two|three|four|five|six)\s+days?\b[^.\n]{0,80}\b(?:trend|trending|consistently|steadily|declin\w*|improv\w*)\b', r'\b(?:trend|trending)\b[^.\n]{0,60}\b(?:last|past)\s+(?:[1-6]|two|three|four|five|six)\s+days\b'],
  message="Trend on fewer than 7 days: '{match}'",
  why="Three days is noise, and the most recent days are still collecting conversions.",
  fix="Call a trend only on 7 or more complete days, or say the data is too new to judge.",
  examples={"flag": ["Over the last 3 days, CPA has been trending down."], "pass": ["Over the last 28 days, CPA fell 12%."]}),
dict(category="watchout", slug="tiny-spend-waste", name="Tiny spend called waste", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'\b(?:wasted?|wasting|wasteful|waste\s+of)\b[^.\n]{0,60}\$\s?\d{1,2}(?:\.\d+)?\b(?!\s?[km])', r'\$\s?\d{1,2}(?:\.\d+)?\b(?!\s?[km])[^.\n]{0,60}\b(?:wasted?|wasting|without\s+convert\w*)\b'],
  message="Small spend flagged as waste: '{match}'",
  why="A $10 line item in a $100k account isn't a finding. Flagging it costs the reader attention and the writer credibility.",
  fix="Drop items under about 5% of spend unless they caused a total-level change.",
  examples={"flag": ["Tablet traffic wasted $12 without converting."], "pass": ["Tablet spend was $4,800 with 2 conversions."]}),
dict(category="watchout", slug="platform-roas-as-cause", name="Platform ROAS stated as cause", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'\b(?:drove|driving|generated|delivered|caused|produced)\b[^.\n]{0,40}\b(?:ROAS|revenue|conversions|sales)\b', r'\bROAS\b[^.\n]{0,40}\b(?:proves?|shows?\s+that|confirms?)\b'],
  unless=r'\b(?:platform[- ]reported|as reported by|attributed|incremental|holdout|lift\s+test|backend|shopify|crm|blended|MER)\b',
  message="Attribution stated as cause: '{match}'",
  why="Platform ROAS is the platform grading its own homework. 'Drove' claims causation the attribution model can't prove.",
  fix="Say 'platform-reported' or 'attributed', or check against backend revenue or a holdout.",
  examples={"flag": ["The PMax campaign drove $84k in revenue."], "pass": ["The PMax campaign was attributed $84k in revenue (platform-reported)."]}),
dict(category="watchout", slug="black-box-campaign", name="Black-box campaign with no caveat", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'\b(?:PMax|Performance\s+Max|AI\s+Max|Advantage\+(?:\s+(?:shopping|campaigns?))?)\b'],
  unless=r"\b(?:can't\s+see|cannot\s+see|doesn't\s+show|does\s+not\s+show|limited\s+visibility|no\s+(?:search\s+term|placement|channel)\s+(?:data|breakdown)|channel\s+report|by\s+channel|opaque|black\s+box|not\s+broken\s+out)\b",
  message="No 'what we can't see' for this campaign: '{match}'",
  why="PMax, AI Max and Advantage+ hide much of where the money goes. A result from them needs a line on what isn't visible.",
  fix="Add what the report can't see (channel mix, search terms, placements) or use the channel breakdown if it exists.",
  examples={"flag": ["PMax delivered a 4.2x ROAS this month."], "pass": ["PMax reported a 4.2x ROAS; we can't see its channel mix this month."]}),
dict(category="watchout", slug="platform-ai-summary", name="Platform AI summary repeated", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'\b(?:Ads\s+Advisor|Analytics\s+Advisor|Ask\s+Advisor|Gemini\s+in\s+Google\s+Ads|Meta\s+AI|Meta\s+business\s+assistant|Muse)\b[^.\n]{0,60}\b(?:says|said|found|recommends|recommended|suggests|identified|shows)\b'],
  message="Claim taken from a platform's own AI: '{match}'",
  why="The platform's AI summary is written by the company that sells the ads. Its claims need checking before they're repeated.",
  fix="Check the claim against the account data or backend before passing it on, or attribute it plainly.",
  examples={"flag": ["Ads Advisor found that Sunday bids are too low."], "pass": ["Sunday CPA was $138 against $101 on other days."]}),
dict(category="watchout", slug="click-spike-no-conversions", name="Click spike with no conversions", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'\b(?:clicks?|CTR|sessions|traffic)\b[^.\n]{0,40}\b(?:spiked|surged|jumped|doubled|tripled|soared)\b'],
  unless=r'\b(?:conversions?|leads|orders|sales|revenue)\b[^.\n]{0,30}\b(?:rose|up|grew|increased|doubled|followed)\b',
  message="Click or CTR spike, check for bots: '{match}'",
  why="Bots made 10 times more clicks than humans in unprotected campaigns (DoubleVerify). A spike with no conversions isn't a win.",
  fix="Check conversions, landing-page views and placements for the same window before reporting the spike as good news.",
  examples={"flag": ["CTR spiked to 4.8% on Display this week."], "pass": ["Clicks doubled and conversions rose 90% with them."]}),
dict(category="watchout", slug="conversions-vs-all-conversions", name="Conversions and all conversions mixed", severity="advisory", engine="regex", applies_to="text",
  patterns=[r'\ball\s+conversions\b'],
  message="Check which conversion column is used: '{match}'",
  why="'All conversions' includes secondary actions and cross-device estimates. Mixed with 'conversions', the math doesn't tie.",
  fix="Use one column throughout and say which.",
  examples={"flag": ["CPA was $42 based on all conversions."], "pass": ["CPA was $42 based on primary conversions."]}),
]
PFX = {"shape": "S", "actions": "A", "watchout": "W"}
for r in R:
    cat = r["category"]
    doc = {"id": f"{PFX[cat]}-{r['slug']}"}
    doc.update({k: r[k] for k in ["slug", "name", "category", "severity", "engine", "applies_to"]})
    for k in ["phrases", "patterns", "count", "unless"]:
        if k in r: doc[k] = r[k]
    doc.update({k: r[k] for k in ["message", "why", "fix", "examples"]})
    doc["source"] = "Research rounds 1–3; locked 2026-10-12."
    d = os.path.join(ROOT, cat); os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, f"{r['slug']}.yaml"), "w") as f:
        yaml.safe_dump(doc, f, sort_keys=False, allow_unicode=True, width=1000)
print(len(R), "rules written")
